std::vector<std::vector<long long> > mergeIntervals(std::vector<std::vector<long long> > intervals) {
    std::sort(intervals.begin(), intervals.end());
    std::vector<std::vector<long long> > out;
    for (std::size_t i = 0; i < intervals.size(); ++i) {
        long long start = intervals[i][0], end = intervals[i][1];
        if (!out.empty() && start <= out.back()[1]) {
            out.back()[1] = std::max(out.back()[1], end);
        } else {
            std::vector<long long> pair;
            pair.push_back(start);
            pair.push_back(end);
            out.push_back(pair);
        }
    }
    return out;
}
